ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"error" : {
		"code" 		: error.errorType.namespace ++ ":" ++ error.errorType.identifier,
		"category" 	: "Technical",
		"flowName"	: vars.flowName default "N/A",
		"message" 	: if (vars.errorDesc == null) error.description else vars.errorDesc as String,
		"details"	: error.detailedDescription
	}
}
